import{_ as i,a0 as a,w as p,s as u,ao as r,I as e,a1 as l,A as n,x as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"什么是黄金镜像？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是黄金镜像？ | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什么是黄金镜像？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是黄金镜像？ | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190711 What is a golden image","title":"什么是黄金镜像？","tag":"201908","desc":""},"relativePath":"201908/20190711 What is a golden image.md","filePath":"[post].md"}'),g={name:"201908/20190711 What is a golden image.md"};function m(d,t,f,x,T,b){const o=a("Link");return p(),u("div",null,[t[25]||(t[25]=r('<h1 id="什么是黄金镜像" tabindex="-1">什么是黄金镜像？ <a class="header-anchor" href="#什么是黄金镜像" aria-label="Permalink to “什么是黄金镜像？”">​</a></h1><blockquote><p>正在开发一个将广泛分发的项目吗？了解一下黄金镜像吧，以便在出现问题时轻松恢复到“完美”状态。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/08/184231ivv745lukchbrhul.jpg" alt=""></p><p>如果你正在从事于质量保证、系统管理或媒体制作（没想到吧），你可能听说过<ruby>正式版<rt>gold master</rt></ruby>这一术语的某些变体，如<ruby>黄金镜像<rt>golden image</rt></ruby>或<ruby>母片<rt>master image</rt></ruby>等等。这个术语已经进入了每个参与创建<strong>完美</strong>模具的人的集体意识，然后从该模具中产生许多复制品。母片或黄金镜像就是：一种虚拟模具，你可以从中打造可分发的模型。</p><p>在媒体制作中，这就是所有人努力开发母片的过程。这个最终产品是独一无二的。它看起来和听起来像是可以看和听的最好的电影或专辑（或其他任何东西）。可以制作和压缩该母片的副本并发送给急切的公众。</p><p>在软件中，与该术语相关联的也是类似的意思。一旦软件经过编译和一再测试，完美的构建成果就会被声明为<strong>黄金版本</strong>，不允许对它进一步更改，并且所有可分发的副本都是从此母片生成的（当软件是用 CD 或 DVD 分发时，这实际上就是母盘）。</p><p>在系统管理中，你可能会遇到你的机构所选的操作系统的黄金镜像，其中的重要设置已经就绪，如安装好的虚拟专用网络（VPN）证书、设置好的电子邮件收件服务器的邮件客户端等等。同样，你可能也会在虚拟机（VM）的世界中听到这个术语，其中精心配置了虚拟驱动器的黄金镜像是所有克隆的新虚拟机的源头。</p><h3 id="gnome-boxes" tabindex="-1">GNOME Boxes <a class="header-anchor" href="#gnome-boxes" aria-label="Permalink to “GNOME Boxes”">​</a></h3><p>正式版的概念很简单，但往往忽视将其付诸实践。有时，你的团队很高兴能够达成他们的目标，但没有人停下来考虑将这些成就指定为权威版本。在其他时候，没有简单的机制来做到这一点。</p><p>黄金镜像等同于部分历史的保存和提前备份计划。一旦你制作了一个完美的模型，无论你正在努力做什么，你都应该为自己保留这项工作，因为它不仅标志着你的进步，而且如果你继续工作时遇到问题，它就会成为一个后备。</p>',10)),e("p",null,[l(o,{href:"https://wiki.gnome.org/Apps/Boxes"},{default:n(()=>[...t[0]||(t[0]=[s("GNOME Boxes",-1)])]),_:1}),t[2]||(t[2]=s("，是随 GNOME 桌面一起提供的虚拟化平台，可以用作简单的演示用途。如果你从未使用过 GNOME Boxes，你可以在 Alan Formy-Duval 的文章 ",-1)),l(o,{href:"https://opensource.com/article/19/5/getting-started-gnome-boxes-virtualization"},{default:n(()=>[...t[1]||(t[1]=[s("GNOME Boxes 入门",-1)])]),_:1}),t[3]||(t[3]=s("中学习它的基础知识。",-1))]),t[26]||(t[26]=e("p",null,"想象一下，你使用 GNOME Boxes 创建虚拟机，然后将操作系统安装到该 VM 中。现在，你想要制作一个黄金镜像。GNOME Boxes 已经率先摄取了你的安装快照，可以作为更多的操作系统安装的黄金镜像。",-1)),t[27]||(t[27]=e("p",null,[s("打开 GNOME Boxes 并在仪表板视图中，右键单击任何虚拟机，然后选择"),e("strong",null,"属性"),s("。在"),e("strong",null,"属性"),s("窗口中，选择"),e("strong",null,"快照"),s("选项卡。由 GNOME Boxes 自动创建的第一个快照是“Just Installed”。顾名思义，这是你最初安装到虚拟机上的操作系统。")],-1)),t[28]||(t[28]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/uploads/snapshots.jpg",alt:"The Just Installed snapshot, or initial golden image, in GNOME Boxes.",title:"The Just Installed snapshot, or initial golden image."})],-1)),t[29]||(t[29]=e("p",null,"如果你的虚拟机变成了你不想要的状态，你可以随时恢复为“Just Installed”镜像。",-1)),e("p",null,[t[5]||(t[5]=s("当然，如果你已经为自己调整了环境，那么在安装后恢复操作系统将是一个极大的工程。这就是为什么虚拟机的常见工作流程是：首先安装操作系统，然后根据你的要求或偏好修改它，然后拍摄快照，将该快照声明为配置好的黄金镜像。例如，如果你使用虚拟机进行 ",-1)),l(o,{href:"https://opensource.com/business/16/8/flatpak"},{default:n(()=>[...t[4]||(t[4]=[s("Flatpak",-1)])]),_:1}),t[6]||(t[6]=s(" 打包，那么在初始安装之后，你可以添加软件和 Flatpak 开发工具，构建工作环境，然后拍摄快照。创建快照后，你可以重命名该虚拟机以指示其真实用途。",-1))]),t[30]||(t[30]=r('<p>要重命名虚拟机，请在仪表板视图中右键单击其缩略图，然后选择<strong>属性</strong>。在<strong>属性</strong>窗口中，输入新名称：</p><p><img src="https://opensource.com/sites/default/files/uploads/boxes-rename_0.jpg" alt="Renaming your VM image in GNOME Boxes." title="Renaming your virtual machine in GNOME Boxes."></p><p>要克隆你的黄金映像，请右键单击 GNOME Boxes 界面中的虚拟机，然后选择<strong>克隆</strong>。</p><p><img src="https://opensource.com/sites/default/files/uploads/boxes-clone.jpg" alt="Cloning your golden image in GNOME Boxes." title="Cloning your golden image in GNOME Boxes."></p><p>你现在可以从黄金映像的最新快照中克隆了。</p><h3 id="黄金镜像" tabindex="-1">黄金镜像 <a class="header-anchor" href="#黄金镜像" aria-label="Permalink to “黄金镜像”">​</a></h3>',6)),e("p",null,[t[8]||(t[8]=s("很少有学科无法从黄金镜像中受益。无论你是在 ",-1)),l(o,{href:"https://git-scm.com"},{default:n(()=>[...t[7]||(t[7]=[s("Git",-1)])]),_:1}),t[9]||(t[9]=s(" 中标记版本、在 Boxes 中拍摄快照、出版原型黑胶唱片、打印书籍以进行审核、设计用于批量生产的丝网印刷、还是制作文字模具，到处都是各种原型。这只是现代技术让我们人类更聪明而不是更努力的另一种方式，因此为你的项目制作一个黄金镜像，并根据需要随时生成克隆吧。",-1))]),t[31]||(t[31]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=s("via: ",-1)),l(o,{href:"https://opensource.com/article/19/7/what-golden-image"},{default:n(()=>[...t[10]||(t[10]=[s("https://opensource.com/article/19/7/what-golden-image",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=s("作者：",-1)),l(o,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[12]||(t[12]=[s("Seth Kenlon",-1)])]),_:1}),t[17]||(t[17]=s(" 选题：",-1)),l(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[13]||(t[13]=[s("lujun9972",-1)])]),_:1}),t[18]||(t[18]=s(" 译者：",-1)),l(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[s("wxy",-1)])]),_:1}),t[19]||(t[19]=s(" 校对：",-1)),l(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[15]||(t[15]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=s("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[20]||(t[20]=[s("LCTT",-1)])]),_:1}),t[23]||(t[23]=s(" 原创编译，",-1)),l(o,{href:"https://linux.cn/"},{default:n(()=>[...t[21]||(t[21]=[s("Linux中国",-1)])]),_:1}),t[24]||(t[24]=s(" 荣誉推出",-1))])])}const B=i(g,[["render",m]]);export{C as __pageData,B as default};
